 if(audioPlaying){for(let r of cassetteReels)r.rotation.y+=dt*2;vinyl.rotation.y+=dt*3.49;}arm.rotation.y=THREE.MathUtils.lerp(arm.rotation.y,vinylMode&&audioPlaying?-.46:0,dt*3);lid.rotation.x=THREE.MathUtils.lerp(lid.rotation.x,vinylMode?-.9:-.38,dt*2);blades.rotation.z-=dt*20;fanHead.rotation.y=Math.sin(t*.4)*.23;
